        Elseif Field.GetDbDataType = DbDataType.DateTime Then

            If Field.DataDomain = DbDataDomain.MSec Then

                Debug.WriteLine("Поле " + Field.Name + " хранит дату и время с точностью до миллисекунд");

            End If;

        End If;

    End For;

    Cur.Close;

    Com.Close;

