	    Dim := Mb.ItemById("DICT_INDICATORS").Bind As IDimensionModel;

	    AArea.DictionaryKey := (Dim As IMetabaseObject).Key;

	    AArea.AttributeKey := Dim.Attributes.Name.Key;

