	Begin

	    // Значения элементов в массивах arr2 и arr3 до изменения

	    Debug.WriteLine("---До преобразований---");

	    Debug.WriteLine(arr2[0, 0]);

	    Debug.WriteLine(arr3[2]);

	    // Изменение значений элементов массивов

	    arr2[0, 0] := 101;

	    arr3[2] := "C";

