	    Matr[1, 0] := 2; Matr[1, 1] := 15; Matr[1, 2] := 7;

	    Matr[2, 0] := 8; Matr[2, 1] := 5; Matr[2, 2] := 13;

	    Debug.WriteLine("Первый массив до выполнения операции:");

	    // Выведем созданный массив в консоль

	    For i := 0 To Matr.GetUpperBound(1) Do

	        For j := 0 To Matr.GetUpperBound(2) Do

	            Debug.Write(Matr[i, j].ToString + " ");

	        End For;

	        Debug.WriteLine("");

	    End For;

	    // Создадим двумерный массив, который будет использоваться во время операции

	    Matr2 := New Double[3, 3];

	    Matr2[0, 0] := 1; Matr2[0, 1] := 2; Matr2[0, 2] := 1;

	    Matr2[1, 0] := 2; Matr2[1, 1] := 1; Matr2[1, 2] := 5;

	    Matr2[2, 0] := 3; Matr2[2, 1] := 4; Matr2[2, 2] := 2;

	    Debug.WriteLine("Второй массив для выполнения операции:");

	    // Выведем созданный массив в консоль

	    For i := 0 To Matr2.GetUpperBound(1) Do

	        For j := 0 To Matr2.GetUpperBound(2) Do

	            Debug.Write(Matr2[i, j].ToString + " ");

	        End For;

	        Debug.WriteLine("");

	    End For;

	    // Выполним арифметическую операцию над элементами массива

	    Matr.ArrayOperation(ArrayOperationType.Minus, Matr2);

	    // Выведем результат операции в консоль

	    Debug.WriteLine("Первый массив после выполнения операции:");

	    For i := 0 To Matr.GetUpperBound(1) Do

	        For j := 0 To Matr.GetUpperBound(2) Do

	            Debug.Write(Matr[i, j].ToString + " ");

	        End For;

	        Debug.WriteLine("");

	    End For;

	End Sub UserProc;

Sub UserProc;

Var

    arrI1: Array[3] Of Integer = [1, 2, 3, 4];

    arrI2: Array[3] Of Integer = [9, 7, 5];

    arrI3: Array[2, 2] Of Integer = [[1, 2], [3, 4]];

    arrI4: Array[1, 2] Of Integer = [[5, 6]];

    arrI5: Array[2, 1] Of Integer = [5, 6];

    arrNewI: Array Of Integer;

    arrS1: Array[2, 2] Of String = [

        ["AA", "AB"],

        ["BA", "BB"]];

    arrS2: Array[2, 2] Of String = [

        ["CC", "CD"],

        ["DC", "DD"]];

    arrNewS: Array Of String;

Begin

    // Объединение двух одномерных массивов

    arrNewI := arrI1.Concat(ArrI2) As Array Of Integer;

    Debug.WriteLine("Length: " + arrNewI.Length.ToString);

    // Объединение двух двухмерных массивов

    // по первому измерению

    arrNewI := arrI3.Concat(ArrI4, 1) As Array Of Integer;

    PrintArr2dV(arrNewI.ToVariantArray, "---Объединение по первому измерению---");

    // по второму измерению

    arrNewI := arrI3.Concat(ArrI5, 2) As Array Of Integer;

    PrintArr2dV(arrNewI.ToVariantArray, "---Объединение по второму измерению---");

    // Символьные массивы

    arrNewS := arrS1.Concat(arrS2, 2) As Array Of String;

    PrintArr2dV(arrNewS.ToVariantArray, "---Символьные массивы---");

End Sub UserProc;

Sub PrintArr2dV(arr: Array Of Variant; title: String);

Var

    i, j: Integer;

Begin

    Debug.WriteLine(title);

    Debug.WriteLine("[");

    For i := arr.GetLowerBound(1) To arr.GetUpperBound(1) Do

        Debug.Indent;

        Debug.Write("[");

        For j := arr.GetLowerBound(2) To arr.GetUpperBound(2) Do

            Debug.Write(String.Format("{0}{1}", arr[i, j], (j < arr.GetUpperBound(2)? ", " : "")));

        End For;

        Debug.WriteLine(String.Format("{0}", (i < arr.GetUpperBound(1)? "], " : "]")));

        Debug.Unindent;

    End For;

    Debug.WriteLine("]");

    Debug.WriteLine("");

End Sub PrintArr2dV;

