    // Получим объект-родитель настроек стиля

    StOwner := StyleSettings.Owner;

    If StOwner = Null Then

        Debug.WriteLine("У настроек стиля заголовка нет объекта-родителя");

    Else

    // Выведем в окно консоли ключ для связи

