    Var

        MB: IMetabase;

        DBInst: IDatabaseInstance;

        SC: ISecurityConnection2;

        SCAsync: ISecurityConnection;

        Command: IDalCommand;

        DalTask: IDalCommandTask;

        Next1: OneTaskAction;

        Next2: TwoTaskAction;

    Begin

        MB := MetabaseClass.Active;

