    // Параметры алгоритма расчёта

    ParamValues := BaseExecutor.ParamValues;

    ParamValues.StartDate := DateTime.ComposeDay(2000, 1, 1);

    ParamValues.EndDate := DateTime.ComposeDay(2020, 1, 1);

