    CalcAlgo := Algo As ICalcAlgorithm;

    // Формирование списка объектов алгоритма

    CalcList := CalcAlgo.Items.Clone;

    // Запуск алгоритма в режиме отладки

    CalcDebug := CalcAlgo.Debug(CalcList);

