    i: Integer;

    ValueFlags: Array Of Integer;

Begin

    MB := MetabaseClass.Active;

    CubInst := MB.ItemById("STD_CUBE").Open(Null) As ICubeInstance;

    Des := CubInst.Destinations.DefaultDestination;

    //Отметка куба

    Sels := Des.CreateDimSelectionSet;

