            Debug.WriteLine(i.ToString + " : "

            + Entry.DateBegin.ToString + ","

            + Entry.RecordNumber.ToString + ","

            + Entry.Field + ","

            + Entry.ErrorMessage);

            If i >= 10 - 1 Then

                Break;

            End If;

        End For;

    End If;

