        // Просмотр матрицы

        ShowMatrix(Matr);

        // Обновление данных в кеше из источника

        InMem.UpdateBySelection(DestInst, DimSS);

    Else

        InMem.PrepareMatrixPartial(DestInst, DimSS);

    End If;

