Sub ShowMatrix(Matr: IMatrix);

Var

    Iter: IMatrixIterator;

Begin

    If Matr.Count <> 0 Then

        Iter := Matr.CreateIterator;

        Iter.Move(IteratorDirection.First);

        While Iter.Valid Do

            Debug.Write(Iter.Value + " ");

            Iter.Move(IteratorDirection.Next);

        End While;

        Debug.WriteLine("");

    Else

        Debug.WriteLine("Empty");

    End If;

End Sub ShowMatrix;

