Sub UserProc;

Var

    MB: IMetabase;

    Db: IDatabase;

    CrInfo: IMetabaseObjectCreateInfo;

    TextProvider: IDtTextProvider;

    Fields: IDtFieldDefinitions;

    TCreator: ITableCreator;

    Conv: Converter;

    TmpTable: ITable;

Begin

    // Получаем текущий репозиторий

    MB := MetabaseClass.Active;

    // Создаем источник данных для таблицы

    TextProvider := New DtTextProvider.Create;

    // Указываем файл, из которого будут загружены данные

    TextProvider.File := "c:\result.txt";

    // Указываем строку с заголовками

    TextProvider.HeaderRow := 1;

    // Указываем символ, разделяющий поля

    TextProvider.DelimitedColumnDelimiter := ";";

    // Задаем формат дат в файле

    TextProvider.StringDataFormat.DateFormat := "ГГГГ";

    // Получаем поля из файла-источника

    Fields := TextProvider.Fields;

    // Указываем тип данных полей

    Fields.Item(0).DataType := DbDataType.String;

    Fields.Item(1).DataType := DbDataType.String;

    Fields.Item(2).DataType := DbDataType.String;

    Fields.Item(3).DataType := DbDataType.DateTime;

    Fields.Item(4).DataType := DbDataType.Float;

    // Создаем объект, предназначенный для создания полей

    TCreator := New TableCreator.Create;

    // Указываем источник данных для создаваемой таблицы

    TCreator.Source := TextProvider;

    // Создаем информацию о создаваемой таблице

    CrInfo := MB.CreateCreateInfo;

    // Указываем папку, в которой будет создана таблица

    CrInfo.Parent := MB.ItemById("FTable");

    // Указываем информацию о создаваемой таблице

    TCreator.ObjectCreateInfo := CrInfo;

    // Получаем базу данных

    Db := MB.ItemById("DB").Bind As IDatabase;

    // Указываем базу данных, в которой будут храниться данные таблицы

    TCreator.Database := Db;

    // Указываем строку в источнике данных,
 начиная с которой будут загружаться данные

    TCreator.DataRow := 0;

    // Указываем количество строк, которое нужно загрузить

    TCreator.RowCount := 100;

    // Указываем, что пустые строки будут пропущены

    TCreator.SkipEmptyRows := True;

    // Создаем преобразователь значений

    Conv := New Converter.Create;

    // Указываем, что значения поля «Value» должны быть преобразованы

    TCreator.AddConverter("Value", Conv);

    // Создаем таблицу и загружаем в неё данные

    TmpTable := TCreator.Execute;

    // Сохраняем созданную таблицу

    (TmpTable As IMetabaseObject).Save;

End Sub UserProc;

Sub UserProc;

Var

    mb: IMetabase;

    Inst: IRubricatorInstance;

    ArrVali: Array[0..1] Of Integer;

    MatCop, Mat: IMatrix;

    CooSrc, CooRes: IMatrixCoord;

    ItSrc, ItRes: IMatrixIterator;

    vVal: Variant;

    ValiDExecKey: Integer;

    ValiRun: IValidationExecRun;

    ValiData: IValidationExecData;

    Sel: IDimSelectionSet;

    Revi: IRubricatorRevision;

    bByScenario: Boolean;

Begin

    mb := MetabaseClass.Active;

    Inst := mb.ItemById("FC_COMM").Open(Null) As IRubricatorInstance;

    ValiDExecKey := 80;

    ValiData := Inst.GetValidationExecData(ValiDExecKey, DictionaryGetDataOptions.None);

    bByScenario := ValiData.ByScenario;

    Sel := Null;

    ValiRun := Inst.LoadValidationRun(ValiData, New ValidationExecSelection.CreateSelection(Sel));

    Mat := ValiRun.Matrix;

    MatCop := ((New MatrixFactory.Create) As IMatrixFactory).CreateMatrix(Mat.Dimensions);

    MatCop.OperationMatrix(MatrixOperation.Append, Mat);

    Mat.Clear;

    Mat.ValueFlag := 1;

    ItSrc := MatCop.CreateIterator;

    CooSrc := MatCop.CreateCoord;

    ItRes := Mat.CreateIterator;

    CooRes := Mat.CreateCoord;

    ItSrc.Move(IteratorDirection.First);

    While ItSrc.Valid Do

        ItSrc.PutCurrentPos(CooSrc);

        CooRes.Assign(CooSrc);

        ItRes.PutCoord(CooRes);

        ItRes.ValueFlag := 0;

            vVal := ItSrc.Value;

            If Not vVal.IsEmpty Then

                ItRes.Value := (vVal As Double) = 0.0 ? 0 : 1;

            End If;

            ItRes.ValueFlag := 1;

        ItSrc.Move(IteratorDirection.Next);

    End While;

    ValiData := Inst.GetValidationExecData(-1, DictionaryGetDataOptions.Create);

    ValiData.Name := (Inst As IMetabaseObjectInstance).Object.Name;

    ValiData.ByScenario := bByScenario;

    ArrVali[0] := 3668;

    ArrVali[1] := 3677;

    ValiData.Validations := ArrVali;

    (ValiData As IRubricatorRecord).Save;

    ValiDExecKey := ValiData.Key;

    ValiRun.EphemeralFacts := False;

    Debug.WriteLine("Признак расчета в измерении сценариев: " + ValiRun.ByScenario.ToString);

    Revi := Inst.OpenRevision("Validation");

    ValiRun.Revision := Revi;

    Inst.SaveValidationRun(ValiRun, ValiData);

End Sub UserProc;

