Class Converter: Object, IValueConverter

    // Функция преобразования значений

    Public Function Convert(Value: Variant): Variant;

    Begin

        // Выполняем округление значения

        Return Math.Round(Value As Double,2);

    End Function Convert;

    // Возвращаем тип преобразованных значений

    Public Function get_DataType: DbDataType;

    Begin

        Return dbDataType.Float;

    End Function get_DataType;

    // Функция для проверки возможности преобразования значения

    Public Function TryConvert(Value: Variant; Var Result: Variant): Boolean;

    Begin

        Try

            // Если преобразование возможно, то функция вернёт значение True

            Result := Convert(Value);

            Return True;

        Except

        End Try;

        // Если преобразование невозможно, то функция вернёт значение False

        Return False;

    End Function TryConvert;

End Class Converter;

Sub UserProc;

Var

    Mb: IMetabase;

    Cube: ICubeInstance;

    CubeDest: ICubeInstanceDestination;

    Sels: IDimSelectionSet;

    Sel: IDimSelection;

    CubeExec: ICubeInstanceDestinationExecutor;

    MatrixVirtual : IMatrix;

Begin

    Mb := MetabaseClass.Active;

    // Открываем куб

    Cube := Mb.ItemById("VIRT_CUBE").Open(Null) As ICubeInstance;

    CubeDest := Cube.Destinations.DefaultDestination;

    // Обработчик событий

    (Cube As IVirtualCubeInstance).ExecuteCallback := New VirtualCubeExecCallback.Create;

    // Отметка для выполнения

    Sels := CubeDest.CreateDimSelectionSet;

    For Each Sel In Sels Do

        Sel.SelectElement(0, False);

    End For;

    // Создаём объект для расчёта куба с флагом доступа к матрицам источников

    CubeExec := CubeDest.CreateExecutorO(CubeInstanceDestinationExecutorOptions.KeepSourceMatrices);

    // Выполняем куб

    CubeExec.PrepareExecute(Sels);

    CubeExec.PerformExecute;

    // Получаем рассчитанную матрицу с данными

    MatrixVirtual := CubeExec.Matrix;

    ShowMatrix("Матрица виртуального куба", MatrixVirtual);

End Sub UserProc;

Public Class VirtualCubeExecCallback: Object, IVirtualCubeExecuteCallback

    Public Sub OnBeforeExecuteSources(Value: IVirtualCubeSourceSelections);

    Var

        i: Integer;

        Sels: IDimSelectionSet;

        Sel: IDimSelection;

    Begin

        For i := 0 To Value.Count - 1 Do

            Sels := Value.Item(i).Selection;

            // Изменение отметки для расчёта источников

            For Each Sel In Sels Do

                Sel.SelectAll;

            End For;

        End For;

    End Sub OnBeforeExecuteSources;

    Public Sub OnAfterExecuteSources(Value: IVirtualCubeSourceMatricesList);

    Var

        i, j: Integer;

        SourceMatrix: IVirtualCubeSourceMatrix;

    Begin

        j := Value.Count;

        Debug.WriteLine("Количество источников: " + j.ToString);

        // Просмотр матриц, полученных при расчёте источников

        For i := 0 To j - 1 Do

            SourceMatrix := Value.Item(i);

            ShowMatrix(SourceMatrix.SourceKey.ToString, SourceMatrix.Matrix);

        End For;

    End Sub OnAfterExecuteSources;

End Class VirtualCubeExecCallback;

Sub ShowMatrix(Title: String; Matr: IMatrix);

Var

    Iter: IMatrixIterator;

Begin

    Debug.Write(Title + " : ");

    If Matr.Count <> 0 Then

        Iter := Matr.CreateIterator;

        Iter.Move(IteratorDirection.First);

        While Iter.Valid Do

            Debug.Write(Iter.Value + " ");

            Iter.Move(IteratorDirection.Next);

        End While;

        Debug.WriteLine("");

    Else

        Debug.WriteLine("Empty");

    End If;

End Sub ShowMatrix;

Sub CreateMDCalculation;

Var

    MB: IMetabase;

    CrInfo: IMetabaseObjectCreateInfo;

    MObj: IMetabaseObject;

    MDCalc: IMDCalculation;

    Cube: ICubeModel;

    Source: IMDCalculationSource;

    Destination: IMDCalculationDestination;

    FormulasTable: IMDCalculationFormulasTable;

    TableForFormulas: ITable;

    SourceSlice, DestinationSlice: IMDCalculationSlice;

Begin

    MB := MetabaseClass.Active;

    CrInfo := MB.CreateCreateInfo;

    CrInfo.ClassID := MetabaseObjectClass.KE_CLASS_MDCALCULATION;

    CrInfo.Id := "New_MDCalculation";

    CrInfo.Name := "Многомерный расчет на сервере";

    CrInfo.Parent := MB.Root;

    MObj := MB.CreateObject(CrInfo).Edit;

    MDCalc := MObj As IMDCalculation;

    //Указываем БД

    MDCalc.Database := MB.ItemById("DB").Bind As IDatabase;

    //Указываем куб-источник

    Cube := MB.ItemById("STD_SOURCE").Bind As ICubeModel;

    Source := MDCalc.Sources.AddCube(Cube);

    SourceSlice := Source.Slices.FindById("CALENDAR");

    SourceSlice.FixType := MDCalculationSliceFixType.Fixed;

    //Указываем куб-назначение

    Destination := MDCalc.Destination;

    Destination.SetCube(MB.ItemById("STD_DESTINATION").Bind As ICubeModel);

    //Фиксируем календарные измерения

    DestinationSlice := Destination.Slices.FindById("CALENDAR");

    DestinationSlice.FixType := MDCalculationSliceFixType.Fixed;

    SourceSlice.Fixed.Mapping := DestinationSlice;

    //Создаем новую таблицу формул

    FormulasTable := MDCalc.FormulasTable;

    TableForFormulas := FormulasTable.Create;

    FormulasTable.Attach(TableForFormulas);

    MObj.Save;

End Sub CreateMDCalculation;

Sub UserProc;

Var

    MB: IMetabase;

    MObj: IMetabaseObject;

    StandCub: IStandardCube;

    Man: IMatrixAggregatorManager;

    Dim: IStandardCubeDimension;

    Lvl: IDimLevels;

    ChronAggr: IChronologicalMatrixAggregator;

    LevAggr: IChronologicalMatrixLevelAggregator;

    Dest: IStandardCubeDestination;

Begin

    MB := MetabaseClass.Active;

    MObj := MB.ItemById("Std_Cube").Edit;

    StandCub := MObj As IStandardCube;

    //Создаем новый агрегатор

    Man := New MatrixAggregatorManager.Create As IMatrixAggregatorManager;

    //Хронологический механизм агрегации

    ChronAggr := Man.CreateAggregator("ChronologicalMatrixAggregator") As IChronologicalMatrixAggregator;

    //Для измерения - календарь

    Dim := StandCub.Dimensions.FindById("CALENDAR");

    Lvl := Dim.Dimension.Levels;

    ChronAggr.Dimension := Dim.Dimension;

    //Уровень-источник

    LevAggr := ChronAggr.LevelAggregation(Lvl.Item(0));

    //Метод - равномерная дезагрегация

    LevAggr.Operation := ChronologicalAggregatorOperation.UniformDisaggregation;

    //Уровень-приёмник

    LevAggr.SourceLevel := Lvl.Item(1);

    //Установка агрегации по первому элементу измерения фактов

    Dest := StandCub.Destinations.Item(0);

    Dim.Aggregator(1, Dest) := ChronAggr;

    MObj.Save;

End Sub UserProc;

Sub UserProc;

Var

    MB: IMetabase;

    MObj: IMetabaseObject;

    StandCub: IStandardCube;

    Man: IMatrixAggregatorManager;

    Dim: IStandardCubeDimension;

    Lvl: IDimLevels;

    BasicAggr: IBasicMatrixAggregator;

    LevAggr: IBasicMatrixLevelAggregator;

    Dest: IStandardCubeDestination;

Begin

    MB := MetabaseClass.Active;

    MObj := MB.ItemById("Std_Cube").Edit;

    StandCub := MObj As IStandardCube;

    //Создаем новый агрегатор

    Man := New MatrixAggregatorManager.Create As IMatrixAggregatorManager;

    //Основной механизм агрегации

    BasicAggr := Man.CreateAggregator("BasicMatrixAggregator") As IBasicMatrixAggregator;

    //Для измерения D_TO

    Dim := StandCub.Dimensions.FindById("D_TO");

    Lvl := Dim.Dimension.Levels;

    BasicAggr.Dimension := Dim.Dimension;

    //Уровень-приёмник

    LevAggr := BasicAggr.LevelAggregation(Lvl.Item(Lvl.Count - 2));

    //Метод - Фактическое среднее

    LevAggr.Operation := BasicAggregatorOperation.ActualMean;

    //Уровень-источник

    LevAggr.Include(Lvl.Item(Lvl.Count - 1)) := True;

    //Установка агрегации по первому элементу измерения фактов

    Dest := StandCub.Destinations.Item(0);

    Dim.Aggregator(1, Dest) := BasicAggr;

    MObj.Save;

End Sub UserProc;

