Sub UserProc;

Var

    Mb: IMetabase;

    Obj: IMetabaseObject;

    Cub: IVirtualCube;

    Dimension: ICompoundDimension;

    Source: ICompoundDimensionSource;

    dimModel: IDimensionModel;

    dimModel1: IDimensionModel;

    df: IDimSelectionSetFactory;

    Selections: IDimSelectionSet;

    dimModelInstance: IDimInstance;

    CompoundSelection: IDimSelectionSet;

    Cinstance: ICompoundDimensionInstance;

    Instance: IDimInstance;

    el: IDimElements;

    i, j: Integer;

    Sel: ICompoundSelection;

Begin

    Mb := MetabaseClass.Active;

    Obj := Mb.ItemById("CUBE_VIRTUAL").Edit;

    Cub := Obj As IVirtualCube;

    Dimension := Cub.FactDimension As ICompoundDimension;

    If Dimension.CustomContainer <> Null Then

        Dimension.CustomContainer := Null;

    End If;

    Dimension.Sources.Clear;

    Source := Dimension.Sources.Add(1);

    dimModel := Mb.ItemById("OBJ_PD_01").Bind As IDimensionModel;

    dimModel1 := Mb.ItemById("OBJ_PD_02").Bind As IDimensionModel;

    Source.Dimensions.Add(dimModel);

    Source.Dimensions.Add(dimModel1);

    df := New DimSelectionSetFactory.Create;

    Selections := df.CreateDimSelectionSet;

    dimModelInstance := (dimModel As IMetabaseObject).Open(Null) As IDimInstance;

    Selections.Add(dimModelInstance);

    dimModelInstance := (dimModel1 As IMetabaseObject).Open(Null) As IDimInstance;

    Selections.Add(dimModelInstance);

    Selections.Item(0).SelectAll;

    Selections.Item(1).SelectAll;

    CompoundSelection := df.CreateDimSelectionSet;

    Sel := CompoundSelection.AddCompound(1, Selections);

    Cinstance := (Dimension As IMetabaseObject).OpenWithParam(CompoundSelection) As ICompoundDimensionInstance;

    Instance := Cinstance As IDimInstance;

    Debug.WriteLine("Наименования элементов");

    el := Instance.Elements;

    j := Instance.Attributes.FindById("NAME").Attribute.Key;

    For i := 0 To el.Count - 1 Do

        Debug.WriteLine("Элемент " + (i + 1).ToString + ": " + (el.AttributeValue(i, j) As String));

    End For;

    Obj.Save;

End Sub UserProc;

Sub UserProc;

Var

    MB: IMetabase;

    Cube: IVirtualCube;

    Sources: IVirtualCubeSources;

    CDim: ICompoundDimension;

    CSource: ICompoundDimensionSource;

    CSel, Sel: IDimSelectionSet;

    FixInfo: ICubeDimensionFixInfo;

    Fix: ICubeDimensionFix;

    Params: IMetabaseObjectParamValues;

    CDimInst: ICompoundDimensionInstance;

    Instance: IDimInstance;

    Elements: IDimElements;

    Source, i: Integer;

    Arr: Array Of Integer;

Begin

    MB := MetabaseClass.Active;

    Cube := MB.ItemById("Virt_Cube").Bind As IVirtualCube;

    Sources := Cube.Sources;

    //Формирование отметки для открытия составного справочника

    CDim := Cube.FactDimension As ICompoundDimension;

    Sel := (New DimSelectionSetFactory.Create).CreateDimSelectionSet;

    CSel := (New DimSelectionSetFactory.Create).CreateDimSelectionSet;

    For Each CSource In CDim.Sources Do

        Sel.Clear;

        //Формирование отметки в соответствии с отметкой фиксированных измерений в источниках

        FixInfo := Sources.FindByKey(CSource.Key).FixInfo;

        For Each Fix In FixInfo Do

            If Fix.Selection.SelectedCount <> 0 Then

                Fix.Selection.CopyTo(Sel.Add(Fix.Instance), True);

            End If;

        End For;

        CSel.AddCompound(CSource.Key, Sel);

    End For;

    //Открытие составного справочника

    Params := (CDim As IMetabaseObject).Params.CreateEmptyValues;

    Params.FindById("SELECTIONS").Value := CSel;

    CDimInst := (CDim As IMetabaseObject).Open(Params) As ICompoundDimensionInstance;

    //Получение элементов составного справочника

    Instance := CDimInst As IDimInstance;

    Elements := Instance.Elements;

    //Индекс последнего источника данных

    Source := CDim.Sources.Count - 1;

    //Последний источник данных

    CSource := CDim.Sources.Item(Source);

    //Массив индексов элементов для получения индекса элемента составного справочника

    Arr := New Integer[CSource.Dimensions.Count];

    For i := 0 To CSource.Dimensions.Count - 1 Do

        Arr[i] := 0;

    End For;

    //Индекс элемента в составном справочнике

    i := CDimInst.ComposeElement(Source, Arr);

    If i <> -1 Then

        Debug.WriteLine(Elements.Name(i));

    End If;

End Sub UserProc;

