    WxConsumer.Extension := WxETLConsumer As IWxShapeExtension;

    //Конец создания визуального объекта

    //Выполнение задачи

    Task.Execute(Null);

    //Сохранение объекта задачи ETL

    (Task As IMetabaseObject).Save;

