Var

    MB: IMetabase;

    Object: IMetabaseObject;

    EtlTask: IEtlTask;

    Links: IEtlPlainLinks;

    Link: IEtlPlainLink;

    Output: IEtlPlainOutput;

    Input: IEtlPlainInput;

    Field: IEtlPlainField;

    FieMapp: IEtlPlainLinkFieldMapping;

    i: Integer;

Begin

    MB := MetabaseClass.Active;

    Object := MB.ItemById("ETL").Edit;

    EtlTask := Object As IEtlTask;

    Link := EtlTask.Links.Item(0);

    Input := Link.DestinationObjectInput;

    Output := Link.SourceObjectOutput;

    For i := 0 To Input.Fields.Count-1 Do

        Field := Input.Fields.Item(i);

        FieMapp := Link.Link(Field);

        FieMapp.Type := 0 As EtlPlainLinkFieldMappingType;

        FieMapp.Field := Output.Fields.Item(Input.Fields.Count-i-1);

    End For;

    Object.Save;

End Sub UserProc;

Sub UserProc;

Var

    MB: IMetabase;

    EtlObj: IMetabaseObject;

    EtlTask: IEtlTask;

    Links: IEtlPlainLinks;

    Link: IEtlPlainLink;

    Output: IEtlPlainOutput;

    Field: IEtlPlainField;

    FileMapp: IEtlPlainLinkFieldMapping;

Begin

    // Получим репозиторий

    MB := MetabaseClass.Active;

    // Получим задачу ETL

    EtlObj := MB.ItemById("TASK_ETL").Edit;

    EtlTask := EtlObj As IEtlTask;

    // Получим объект-связку

    Links := EtlTask.Links;

    Link := Links.Item(0);

    // Получим выход источника

    Output := Link.SourceObjectOutput;

    // Получим поле выхода

    Field := Output.Fields.Item(0);

    // Заполним поле с помощью типа связи - автоинкремент

    FileMapp := Link.Link(Field);

    FileMapp.Type := EtlPlainLinkFieldMappingType.Increment;

    // Установим начальное значение

    FileMapp.StartValue := 100;

    // Установим шаг

    FileMapp.Increment := 10;

    // Сохраним изменения

    EtlObj.Save;

End Sub UserProc;

