Sub UserProc;

Var

    MB: IMetabase;

    MbObj: IMetabaseObject;

    EtlTask: IEtlTask;

    Object1, Object2: IEtlObject;

    ActiveChain, CanDeactiv: Boolean;

Begin

    MB := MetabaseClass.Active;

    MbObj := MB.ItemById("ETL").Bind;

    EtlTask := (MbObj) As IEtlTask;

    // состояние цепочки объектов

    ActiveChain := EtlTask.ActiveChain(3);

    If ActiveChain = True Then

        Debug.WriteLine("Цепочка объектов активна");

        Else Debug.WriteLine("Цепочка объектов не активна");

    End If;

    // состояние объекта расчета цепочки

    Object1 := EtlTask.Item(5);

    CanDeactiv := EtlTask.CanDeactivateObject(Object1);

    If CanDeactiv = False Then

        Debug.WriteLine("Объект исключен из цепочки");

        Else Debug.WriteLine("Объект включен в цепочку");

    End If;

    // исключить/включить объект из расчета цепочки

    Object2 := EtlTask.Item(3);

    CanDeactiv := EtlTask.CanDeactivateObject(Object2);

    If CanDeactiv = False Then

        EtlTask.ActivateObject(Object2, False);

        Else EtlTask.ActivateObject(Object2, True);

    End If;

End Sub UserProc;

Sub  UserProc;

Var

    MB: IMetabase;

    ci: IMetabaseObjectCreateInfo;

    MbObj: IMetabaseObject;

    EtlTask: IEtlTask;

    EtlProvider: IEtlPlainDataProvider;

    ExcelProvider: IDtExcelProvider;

    WxConsumer: IWxRectangle;

    WxETLConsumer: IWxEtlObject;

Begin

    MB := MetabaseClass.Active;

    //Создаем новую задачу ETL

    ci := Mb.CreateCreateInfo;

    ci.ClassId := MetabaseObjectClass.KE_CLASS_ETLTASK;

    ci.Parent := MB.ItemById("ETLTASKS");

    ci.Name := "Задача ETL";

    ci.Id := "ETLTASK";

    MbObj := Mb.CreateObject(ci).Edit;

    EtlTask := MbObj As IEtlTask;

    //Создаем объект "Импорт из Excel"

    EtlProvider := EtlTask.Create(EtlObjectType.PlainDataExcelProvider) As IEtlPlainDataProvider;

    EtlProvider := EtlProvider.Edit;

    EtlProvider.Id := "File_XLS";

    EtlProvider.Name := "Источник данных XLS";

    EtlProvider.Description := "Данные из файла data.xls";

    //Настраиваем источник данных

    ExcelProvider := EtlProvider.Provider As IDtExcelProvider;

    ExcelProvider.File := "c:\data.xls";

    ExcelProvider.DriverVersion := "Excel 8.0";

    ExcelProvider.Query := "select * from [Лист1$]";

    ExcelProvider.HasHeader := False;

    EtlProvider.FillDefault;

    //Сохраняем источник Excel

    EtlProvider.Save;

    //Создаем визуальный объект

    WxConsumer := EtlTask.Workspace.CreateRectangle;

    WxETLConsumer := New WxEtlObject.Create;

    WxETLConsumer.EtlObject := EtlProvider;

    WxConsumer.Style.TextPosition := WxTextPosition.Bottom;

    WxConsumer.Style.PictureMarginTop := -10;

    WxConsumer.PinPosition := New GxPointF.Create(50, 50);

    WxConsumer.Extension := WxETLConsumer As IWxShapeExtension;

    //Сохраняем объект репозитория

    MbObj.Save;

End Sub UserProc;

Sub UserProc;

Var

    MB: IMetabase;

    MbObj: IMetabaseObject;

    EtlTask: IEtlTask;

    Link: IEtlPlainLink;

    Provider: IEtlPlainDataProvider;

    Consumer: IEtlPlainDataConsumer;

    WLink: IWxLink;

    Style: IWxStyle;

    WxETLLink: IWxEtlObject;

    WxProvider, WxConsumer: IWxShape;

Begin

    MB := MetabaseClass.Active;

    MbObj := MB.ItemById("ETL").Edit;

    EtlTask := (MbObj) As IEtlTask;

    //Создание нового объекта-связки

    Link := EtlTask.CreatePlainLink;

    //Установка источника и приёмника данных

    Provider := EtlTask.Item(0) As IEtlPlainDataProvider;

    Consumer := EtlTask.Item(1) As IEtlPlainDataConsumer;

    Link.SourceObjectOutput := Provider.PlainOutput;

    Link.DestinationObjectInput := Consumer.PlainInput;

    Link.FillDefault;

    //Создание визуальной связи

    //Прямоугольник источника

    WxProvider := EtlTask.Workspace.Shapes.Item(0);

    //Прямоугольник приёмника

    WxConsumer := EtlTask.Workspace.Shapes.Item(1);

    WLink := EtlTask.Workspace.AutoLinkShapes(WxProvider, WxConsumer);

    WxETLLink := New WxEtlObject.Create;

    WxETLLink.EtlObject := Link;

    WLink.Extension := WxETLLink As IWxShapeExtension;

    //Конец визуального cоздания связи (источник-приёмник)

    MbObj.Save;

End Sub UserProc;

