Sub Button1OnClick(Sender: Object; Args: IMouseEventArgs);

Var

    EaxStat: IEaxStatistics;

    Tree: ITsStatisticsTree;

    i: integer;

    Nodes: ITreeListNodes;

    StatNode, ParentNode: ITreeListNode;

    HashT: IHashtable;

Begin

    EaxStat := UiErAnalyzer1.ErAnalyzer.Statistics;

    // Исключаем часть статистик из построения дерева

    EaxStat.StatisticsVisible(TsStatisticsType.Skew) := False;

    EaxStat.StatisticsVisible(TsStatisticsType.Kurt) := False;

    EaxStat.CustomStatisticsVisible(EaxCustomStatisticsType.Scale) := False;

    // Получаем статистики

    Tree := EaxStat.AllStatistics;

    // Очищаем компонент для вывода дерева статистик

    Nodes := TreeList1.Nodes;

    Nodes.Clear;

    // Отстраиваем дерево

    If Tree = Null Then

        Return;

    End If;

    HashT := New Hashtable.Create;

    For i := 0 To Tree.Count - 1 Do

        ParentNode := Null;

        If Tree.ParentNode(i) <> -1 Then

            ParentNode := HashT(Tree.ParentNode(i));

        End If;

        StatNode := Nodes.AddChild(ParentNode, Tree.Name(i));

        If Tree.Type(i) <> TsStatisticsTreeNodeType.Category Then

            StatNode.ColumnText(1) := Tree.Value(i);

        End If;

        StatNode.Data := i;

        HashT(i) := StatNode;

    End For;

    HashT.Clear;

    Nodes.TreeControl.InnerRoot.Expand(True);

End Sub Button1OnClick;

Sub UserProc;

Var

    MB: IMetabase;

    Report: IPrxReport;

    DataArea: IEaxDataArea;

    RepGrid: IEaxGrid;

    SelManager: IEaxObjectSelectionManager;

    SliceA, SliceB: IEaxDataAreaSlice;

    CalDimKey_A, TerDimKey_A, CalDimKey_B, TerDimKey_B, i, Key, Count: Integer;

    CalInst_A, TerInst_A, CalInst_B, TerInst_B: IEaxDimensionInstance;

    SGroups: IEaxSyncGroups;

    Group_a, Group_b, SG: IEaxSyncGroup;

    Compatible: IEaxDimensionDescriptors;

    DimName, SyncAttr: String;

    SyncItem: IEaxSyncItem;

Begin

    MB := MetabaseClass.Active;

    // Получаем отчет

    Report := MB.ItemById("REG_SYNCGROUPS").Edit As IPrxReport;

    // Получаем объект для работы с таблицей

    DataArea := Report.DataArea;

    RepGrid := DataArea.Views.Item(0) As IEaxGrid;

    SelManager := RepGrid.SelectionManager;

    // Настраиваем синхронизацию измерений первого среза

    SliceA := Report.DataArea.Slices.Item(0);

    CalDimKey_A := SliceA.Selection.FindById("D_CALENDAR").Dimension.Key;

    CalInst_A := SelManager.GetDimension(CalDimKey_A);

    TerDimKey_A := SliceA.Selection.FindById("DIC_RF").Dimension.Key;

    TerInst_A := SelManager.GetDimension(TerDimKey_A);

    SGroups := Report.SyncGroups;

    Group_a := SGroups.CreateGroup(CalInst_A);

    Group_b := SGroups.CreateGroup(TerInst_A);

    SyncItem := Group_a.Add(CalInst_A);

    SyncItem := Group_b.Add(TerInst_A);

    // Настраиваем синхронизацию измерений второго среза

    SliceB := Report.DataArea.Slices.Item(1);

    CalDimKey_B := SliceB.Selection.FindById("D_CALENDAR").Dimension.Key;

    CalInst_B := SliceB.GetDimension(CalDimKey_B);

    TerDimKey_B := SliceB.Selection.FindById("DIC_RF").Dimension.Key;

    TerInst_B := SliceB.GetDimension(TerDimKey_B);

    Compatible := SGroups.GetCompatibleItems(CalInst_A, "");

    DimName := SliceA.Selection.FindById("D_CALENDAR").Dimension.Name;

    Debug.WriteLine("Количество связей, для которых подходит данное измерение = " + Compatible.Count.ToString);

    If SGroups.IsDimensionsCompatible(CalInst_A, "", CalInst_B, "") Then

        Group_a.Add(CalInst_B);

    Else

        Return;

    End If;

    If SGroups.IsDimensionsCompatible(TerInst_A, "", TerInst_B, "") Then

        Group_b.Add(TerInst_B);

    Else

        Return;

    End If;

    // Получаем элементы связи измерения территориальных образований

    SG := SGroups.InGroup(TerInst_B);

    SG.PropogateChanges(TerInst_B);

    For i := 0 To SG.Count - 1 Do

        SyncItem := SG.Item(i);

        // Указываем, что связь только принимает отметку

        SyncItem.SyncDirection := EaxDimensionSynchronizationDirection.ConsumeChangesOnly;

        SyncAttr := SyncItem.SyncAttribute;

        Count := SyncItem.SyncGroup.Count;

        Key := SyncItem.Dimension.DimKey;

        Debug.WriteLine("Количество элементов связи = " + Count.ToString);

        Debug.WriteLine("Ключ измерения - " + Count.ToString);

        If SyncAttr.Length > 0 Then

            Debug.WriteLine("Атрибут синхронизации - " + SyncAttr);

        Else

            Debug.WriteLine("Нет синхронизации по атрибуту");

        End If;

    End For;

    // Сохраним изменения

    (Report As IMetabaseObject).Save;

End Sub UserProc;

Sub UserProc;

Var

    Metabase: IMetabase;

    Analyzer: IEaxAnalyzer;

    Pivot: IPivot;

    ColumnSettings: IPivotParetoSettings;

    BottomSettings: IPivotParetoSettingsItem;

    TopSettings: IPivotParetoSettingsItem;

    Grid: IEaxGrid;

    Style: IEaxTableStyle;

    AbcTopStyle: ITabCellStyle;

    AbcBottomStyle: ITabCellStyle;

    TopBrush: GxSolidBrush;

    BottomBrush: GxSolidBrush;

    TopColor: IGxColor;

    BottomColor: IGxColor;

Begin

    // Получим репозиторий

    Metabase := MetabaseClass.Active;

    // Получим экспресс-отчёт

    Analyzer := Metabase.ItemById("EXPRESS_IPIVOTPARETOSETTENGSITEM").Edit As IEaxAnalyzer;

    // Получим таблицу экспресс-отчета

    Pivot := Analyzer.Pivot;

    // Будем применять анализ 80/20 к столбцам

    ColumnSettings := Pivot.Pareto.ColumnsSettings;

    // Включим анализ только для первого столбца

    ColumnSettings.Enabled := True;

    ColumnSettings.ElementIndex := 0;

    // Получим максимальные значения анализируемого столбца

    TopSettings := ColumnSettings.TopSettings;

    // Изменим тип расчета

    TopSettings.Kind := PivotParetoKind.Count;

    // Включим отображение ячеек с максимальными значениями

    TopSettings.Display := True;

    // Изменим количество отображаемых ячеек с максимальными значениями

    TopSettings.Threshold := 2;

    // Получим минимальные значения анализируемого столбца

    BottomSettings := ColumnSettings.BottomSettings;

    // Изменим тип расчета

    BottomSettings.Kind := PivotParetoKind.Count;

    // Включим отображение ячеек с минимальными значениями

    BottomSettings.Display := True;

    // Изменим количество отображаемых ячеек с минимальными значениями

    BottomSettings.Threshold := 2;

    // Получим таблицу данных отчета

    Grid := Analyzer.Grid;

    // Получим параметры оформления таблицы

    Style := Grid.Style;

    // Создадим и зададим зеленый цвет фона ячеек c максимальными значениями

    AbcTopStyle := New TabCellStyle.Create;

    TopColor := New GxColor.CreateRGB(0, 128, 0);

    TopBrush := New GxSolidBrush.Create(TopColor);

    AbcTopStyle.BackgroundBrush := TopBrush;

    Style.ABCTopStyle := AbcTopStyle;

    // Создадим и зададим красный цвет фона ячеек с минимальными значениями

    AbcBottomStyle := New TabCellStyle.Create;

    BottomColor := New GxColor.CreateRGB(255, 0, 0);

    BottomBrush := New GxSolidBrush.Create(BottomColor);

    AbcBottomStyle.BackgroundBrush := BottomBrush;

    Style.ABCBottomStyle := AbcBottomStyle;

    // Сохраним изменения

    (Analyzer As IMetabaseObject).Save;

End Sub UserProc;

