Sub Button1OnClick(Sender: Object; Args: IMouseEventArgs);

Var

    Ea: IEaxAnalyzer;

    Wb: IEaxWorkbook;

    Ch: IEaxWorkbookChart;

    Cap: IChartCaption;

    Ind: String;

Begin

    Ea := UiErAnalyzer1.ErAnalyzer;

    Wb := Ea As IEaxWorkbook;

    Ch := Wb.Chart;

    If Ch.Type = EaxWorkbookChartType.StatMethod Then

        If Ch.SerieTypeAvailable(EaxWorkbookChartSerieType.UpperConfidenceLevel) Then

            Ch.SerieTypeVisible(EaxWorkbookChartSerieType.UpperConfidenceLevel) := True;

            Ind := Ch.SerieTypeIndex(EaxWorkbookChartSerieType.UpperConfidenceLevel).ToString;

            Debug.WriteLine("Индекс ряда, соответствующего верхней доверительной границе: " + Ind);

        End If;

        If Ch.SerieTypeAvailable(EaxWorkbookChartSerieType.LowerConfidenceLevel) Then

            Ch.SerieTypeVisible(EaxWorkbookChartSerieType.LowerConfidenceLevel) := True;

            Ind := Ch.SerieTypeIndex(EaxWorkbookChartSerieType.LowerConfidenceLevel).ToString;

            Debug.WriteLine("Индекс ряда, соответствующего нижней доверительной границе: " + Ind);

        End If;

    End If;

    Cap := Ch.Chart.Caption;

    Cap.Text := "Диаграмма";

    Cap.Visible := True;

End Sub Button1OnClick;

Sub UserProc;

Var

    MB: IMetabase;

    CrInfo: IMetabaseObjectCreateInfo;

    MObj: IMetabaseObject;

    Exp: IEaxAnalyzer;

    Source: IMetabaseObjectDescriptor;

    WB: IEaxWorkbook;

    Context: ILanerContext;

    Laner: ILaner;

Begin

    // Получаем репозиторий

    MB := MetabaseClass.Active;

    // Задаем базовые параметры создания рабочей книги

    CrInfo := MB.CreateCreateInfo;

    CrInfo.ClassID := MetabaseObjectClass.KE_CLASS_WORKBOOK;

    CrInfo.Id := MB.GenerateId("NEW_WORKBOOK");

    CrInfo.Name := "Новая рабочая книга";

    CrInfo.Parent := MB.ItemById("WORKBOOKS");

    // Создаем объект репозитория «Рабочая книга»

    MObj := MB.CreateObject(CrInfo).Edit;

    Exp := MObj As IEaxAnalyzer;

    WB := Exp As IEaxWorkbook;

    // Задаем источник данных рабочей книги

    Source := MB.ItemById("TSDB");

    Laner := WB.Laner;

    Laner.RubricatorInstance := Source.Open(Null) As IRubricatorInstance;

    // Настраиваем контекст

    WB.UseLanerContext := True;

    Context := WB.LanerContext;

    Context.AllowExternalStubs := True;

    Context.AllowSmartHighlighting := True;

    Context.AllowSynchronization := True;

    //Сохраняем созданный объект репозитория

    MObj.Save;

End Sub UserProc;

Sub UserProc;

Var

    Ea: IEaxAnalyzer;

    Wb: IEaxWorkbook;

    WbTree: IEaxWorkbookMetaAttributesTree;

    Laner: ILaner;

    Rub: IRubricator;

    RubKey: Integer;

    OpList: IEaxWorkbookRubricatorOptionsList;

    Res: Boolean;

Begin

    // Получаем рабочую книгу

    Ea := UiErAnalyzer1.ErAnalyzer;

    Wb := Ea As IEaxWorkbook;

    // Получаем параметры дерева объектов

    WbTree := Wb.MetaAttributesTree;

    Laner := Ea.Laner;

    Rub := Laner.RubricatorInstance.Rubricator;

    RubKey := (Rub As IMetabaseObjectDescriptor).Key;

    // Получаем параметры каталогов, связанных с деревом показателей

    OpList := WbTree.RubricatorsOptions;

    Res := OpList.Remove(RubKey);

    If Res Then

        Debug.WriteLine("Удаление выполнено успешно");

    Else

        Debug.WriteLine("Настройки для указанной базы данных временных рядов отсутствуют");

    End If;

    (Ea As IMetabaseObject).Save;

End Sub UserProc;

