Sub Button1OnClick(Sender: Object; Args: IMouseEventArgs);

Var

    Results: ILanerResultsBoxResults;

    Coefficients: ILanerResultsBoxCoefficients;

    ColumnIndex, i: Integer;

Begin

    Results := LanerResultsBox1.Results;

    Coefficients := Results.Coefficients;

    If Coefficients.TermCount > 0 Then

        Debug.WriteLine("Уравнение:   " + Coefficients.Equation);

        For i := 0 To Coefficients.ColumnCount - 1 Do

            If Coefficients.ColumnType(i) = LanerBoxCoefficentColumns.Coefficient Then

                ColumnIndex := i;

            End If;

        End For;

        For i := 0 To Coefficients.TermCount - 1 Do

            Debug.WriteLine(Coefficients.Value(i, ColumnIndex));

        End For;

    Else

        Debug.WriteLine("Коэффициенты не рассчитывались");

    End If;

End Sub Button1OnClick;

Sub LanerResultsBox1OnCopyStatistics(Sender: Object; Args: ILanerResultsBoxCopyEventArgs);

Var

    LanerResultsBox: ILanerResultsBox;

    Results: ILanerResultsBoxResults;

    Statistics: ILanerResultsBoxStatistics;

    i: Integer;

Begin

    Args.Handled := True;

    LanerResultsBox := Sender As ILanerResultsBox;

    Results := LanerResultsBox.Results;

    Statistics := Results.Statistics;

    For i := 0 To Statistics.Count - 1 Do

        If Statistics.Type(i) = LanerBoxStatisticType.Min Then

            Debug.WriteLine(Statistics.Name(i) + "       " + Statistics.Value(i));

        End If;

    End For;

End Sub LanerResultsBox1OnCopyStatistics;

Sub Button1OnClick(Sender: Object; Args: IMouseEventArgs);

Var

    Results: ILanerResultsBoxResults;

    Coefficients: ILanerResultsBoxCoefficients;

    i, j: Integer;

    s: string;

Begin

    Results := LanerResultsBox1.Results;

    Coefficients := Results.Coefficients;

    If Coefficients.TermCount > 0 Then

        Debug.WriteLine("Уравнение:   " + Coefficients.Equation);

        For i := 0 To Coefficients.ColumnCount - 1 Do

            s := s + "    " + Coefficients.ColumnName(i);

        End For;

        Debug.WriteLine(s);

        For i := 0 To Coefficients.TermCount - 1 Do

            s := "";

            For j := 0 To Coefficients.ColumnCount - 1 Do

                s := s + "    " + Coefficients.Value(i, j);

            End For;

            Debug.WriteLine(s);

        End For;

    Else

        Debug.WriteLine("Коэффициенты не рассчитывались");

    End If;

End Sub Button1OnClick;

