    DiagRep := New DiagnosticReport.Create;

    DiagRep.Run := ValidExecRun;

    Analyzer.DiagnosticReport := DiagRep;

    //Указание источника для компонента

    ValidationLegendBox1.Analyzer := UiErAnalyzer1 As IEaxAnalyzerSource;

