    Atrs: IMetaAttributes;

    Atr: IMetaAttribute;

    AgrGroups: IMsAggregationGroups;

    AgrGroup: IMsAggregationGroup;

    Group: IDimElementGroup;

Begin

    MB := MetabaseClass.Active;

    RKey := MB.ItemById("OBJ_RUBRICATOR").Key;

