	    Debug.Write("     Значение: ");

	    Debug.WriteLine(Stat.Statistic);

	    Debug.Write("     Вероятность: ");

	    Debug.WriteLine(Stat.Probability);

	    Stat := DResults.FTest;

	    Debug.WriteLine("-- Статистика Фишера --");

	    Debug.Write("     Значение: ");

	    Debug.WriteLine(Stat.Statistic);

	    Debug.Write("     Вероятность: ");

