Sub UserProc;

	Var

	    mb: IMetabase;

	    MsKey: Integer;

	    Model: IMsModel;

	    Stub: IVariableStub;

	    Tree: IMsFormulaTransformSlicesTree;

	    RubrDescr: IMetabaseObjectDescriptor;

	    Transform: IMsFormulaTransform;

	    TransformVarables: IMsFormulaTransformVariables;

	    TransformVar: IMsFormulaTransformVariable;

	    Coord: IMsFormulaTransformCoord;

	    Slice: IMsFormulaTransformSlice;

	    Collapse: IMsCollapseTransform;

	    TermInfo: IMsFormulaTermInfo;

	    Calcul: IMsMethodCalculation;

	    arr: Array Of double;

	    i: Integer;

	    Period: IMsModelPeriod;

	Begin

	    // Получаем текущий репозиторий

	    mb := MetabaseClass.Active;

	    // Получаем ключ контейнера моделирования

	    MsKey := mb.GetObjectKeyById("MS");

	    // Получаем модель

	    Model := mb.ItemByIdNamespace("MODEL_COLLAPSE_VECT", MsKey).Edit As IMsModel;

	    // Получаем объект для настройки параметров модели

	    Transform := Model.Transform;

	    // Получаем коллекцию моделируемых переменных

	    TransformVarables := Transform.Outputs;

	    // Получаем первую моделируемую переменную

	    TransformVar := TransformVarables.Item(0);

	    // Создаем параметры расчета моделируемой переменной

	    Coord := Transform.CreateCoord(TransformVar);

	    // Получаем параметры расчета метода «Коллапс»

	    Collapse := Transform.FormulaItem(0).Method As IMsCollapseTransform;

	    // Получаем базу данных временных рядов (БДВР)

	    RubrDescr := Mb.ItemById("TSDB");

	    // Приводим полученную БДВР к абстрактному источнику данных

	    Stub := RubrDescr.Bind As IVariableStub;

	    // Добавляем в модель фактор, источником данных которого является БДВР

	    TransformVar := Transform.Inputs.Add(Stub);

	    Tree := TransformVar.SlicesTree(TransformVar);

	    Slice := Tree.CreateSlice(2);

	    // Получаем фактор в виде терма

	    TermInfo := Transform.CreateTermInfo;

	    TermInfo.Slice := Slice;

	    // Указываем полученный терм в качестве исходной переменной

	    Collapse.Input := TermInfo;

	    // Указываем исходную динамику

	    Collapse.InputLevel := DimCalendarLevel.Month;

	    // Задаем тип коллапса

	    Collapse.MethodType := MsCollapseType.Average;

	    // Указываем метод обработки пропусков

	    Collapse.MissingData.Method := MissingDataMethod.LinTrend;

	    // Задаем количество пропущенных значений в моделируемом ряде,

	    // которое можно считать приемлемыми для выполнения агрегации

	    Collapse.Tolerance := 5;

	    // Создаем объект с параметрами расчета модели

	    Calcul := Transform.CreateCalculation;

	    // Задаем периоды расчета

	    Period := Model.Transform.Period;

	    Calcul.Period.IdentificationStartDate := Period.IdentificationStartDate;

	    Calcul.Period.IdentificationEndDate := Period.IdentificationEndDate;

	    Calcul.Period.ForecastStartDate := Period.ForecastStartDate;

	    Calcul.Period.ForecastEndDate := Period.ForecastEndDate;

	    Calcul.CurrentPoint := Period.IdentificationStartDate;

	    // Получаем данные моделируемой переменной

	    arr := Collapse.CalculateSeries(Calcul, Coord).Modelling;

	    // Выводим наименование и данные моделируемой переменной в окно консоли

	    Debug.WriteLine(Collapse.Result.TermInfo.TermText);

	    For i := 0 To arr.Length - 1 Do

	        Debug.WriteLine(arr[i]);

	    End For;

	    // Сохраняем изменения в модели

	    (Model As IMetabaseObject).Save;

	End Sub UserProc;

Sub UserProc;

Var

    MB: IMetabase;

    Workbook: IEaxAnalyzer;

    Laner: ILaner;

    Factor: IRubricatorFactor;

    Series: ILanerSeries;

    RubrIn: IRubricatorInstance;

    Serie: ILanerCalculateSerie;

    TransformModel: IFormulaTransformModel;

    CalcSerie: ILanerCalculateSerie;

    Selector: IMsFormulaTransformSelector;

    Slice: IMsFormulaTransformSlice;

    MDic: IMetaDictionary;

    MetaAttr: IMetaAttribute;

    MsMetaAttributeValue: IMsMetaAttributeValue;

    Formula: IMsFormula;

    FormulaTransform: IMsFormulaTransform;

    Det: IMsDeterministicTransform;

    Rubricator: IRubricator;

    Info: IMsFormulaTermInfo;

    Term: IMsFormulaTerm;

    TermMeth: IMsFormulaTermTransformationMethod;

    Collapse: IMsCollapseTransformationMethod;

Begin

    // Получим текущий репозиторий

    MB := MetabaseClass.Active;

    // Получим рабочую книгу

    Workbook := MB.ItemById("WORKBOOK").Edit As IEaxAnalyzer;

    // Получим рабочую область каталога показателей

    Laner := Workbook.Laner;

    // Получим коллекцию рядов рабочей области

    Series := Laner.Series;

    // Получим данные базы данных временных рядов

    RubrIn := Laner.RubricatorInstance;

    // Получим временной ряд показателя с ключом «1»

    Factor := RubrIn.GetFactData(1).Factor;

    // Добавим вычисляемый ряд на основе временного ряда

    Serie := Series.AddCalculateSerieAsSource(Factor);

    // Добавим вычисляемый ряд с наименованием «Collapse»

    CalcSerie := Series.AddCalculateSerie("Collapse");

    // Настроим параметры вычисляемого ряда

    TransformModel := CalcSerie.Transform;

    TransformModel.AddInputVariable(Serie.Stub);

    // Настроим параметры метода расчёта

    FormulaTransform := TransformModel.Transform As IMsFormulaTransform;

    Selector := FormulaTransform.CreateSelector;

    Slice := FormulaTransform.Outputs.Item(0).Slices.Add(Null);

    Selector.Slice := Slice;

    Formula := FormulaTransform.Transform(Selector);

    Formula.Kind := MsFormulaKind.Deterministic;

    Formula.Level := DimCalendarLevel.Year;

    Det := Formula.Method As IMsDeterministicTransform;

    Slice := FormulaTransform.Inputs.Item(0).Slices.Add(Null);

    Rubricator := Laner.RubricatorInstance.Rubricator;

    MDic := Rubricator.Facts;

    MetaAttr := MDic.Attributes.FindByKind(MetaAttributeKind.CalendarLevel);

    MsMetaAttributeValue := Slice.MetaAttributeValueList.Add(MetaAttr);

    MsMetaAttributeValue.Value := DimCalendarLevelSet.Quarter;

    Term := Det.Operands.Add(Slice);

    Info := Term.TermInfo;

    TermMeth := Info.CreateTermTransformationMethod(MsTermTransformationType.Collapse);

    Collapse := TermMeth As IMsCollapseTransformationMethod;

    Collapse.CollapseType := MsCollapseType.Maximum;

    Info.TermTransformationMethod := Collapse;

    Det.Expression.AsString := Term.TermToInnerText;

    // Сохраним изменения

    (Workbook As IMetabaseObject).Save;

End Sub UserProc;

