	    Breakpoints := Calculation.Breakpoints;

	    Breakpoints.Clear;

	    Breakpoint := Breakpoints.Add(MsBreakpointKind.Data);

	    DataBreakpoint := Breakpoint As IMsDataBreakpoint;

	    DataBreakpoint.Name := "DataBreakpoint";

