Sub UserProc;

	Var

	    mb: IMetabase;

	    MsKey: Integer;

	    CrInfo: IMetabaseObjectCreateInfo;

	    ProblemCopied, ProblemCopy: IMsProblem;

	    i: Integer;

	    CalcSettCopied, CalcSettCopy: IMsProblemCalculationSettings;

	    PeriodCopied, PeriodCopy: IMsModelPeriod;

	    OutputPeriodCopied, OutputPeriodCopy: IMsDatePeriod;

	    ProblemCalc: IMsProblemCalculation;

	Begin

	    mb := metabaseClass.Active;

	    // Получаем ключ контейнера моделирования

	    MsKey := mb.GetObjectKeyById("MS");

	    // Получаем копируемую задачу

	    ProblemCopied := mb.ItemByIdNamespace("PROBLEM_COPIED", MsKey).Edit As IMsProblem;

	    // Создаем объект для задачи-копии

	    CrInfo := MB.CreateCreateInfo;

	    CrInfo.ClassID := MetabaseObjectClass.KE_CLASS_MSPROBLEM;

	    CrInfo.Id := MB.GenerateId("PROBLEM_COPY", MsKey);

	    CrInfo.Name := "Задача моделирования (копия)";

	    CrInfo.Parent := ProblemCopied.MetabaseObject.Parent;

	    ProblemCopy := MB.CreateObject(CrInfo).Edit As IMsProblem;

	    // Копируем метамодель

	    ProblemCopy.MetaModel := ProblemCopied.MetaModel;

	    // Копируем параметры задачи

	    ProblemCopy.Details := ProblemCopied.Details;

	    // Копируем сценарии

	    For i := 0 To ProblemCopied.Scenarios.Count - 1 Do

	        ProblemCopy.Scenarios.AddScenario(ProblemCopied.Scenarios.Item(i));

	    End For;

	    // Копируем параметры периода выгрузки данных

	    CalcSettCopied := ProblemCopied.CreateCalculationSettings;

	    OutputPeriodCopied := CalcSettCopied.OutputPeriod As IMsDatePeriod;

	    CalcSettCopy := ProblemCopy.CreateCalculationSettings;

	    OutputPeriodCopy := CalcSettCopy.OutputPeriod As IMsDatePeriod;

	    OutputPeriodCopy.Assign(OutputPeriodCopied);

	    // Копируем периоды расчета задачи

	    PeriodCopied := CalcSettCopied.Period;

	    PeriodCopy := CalcSettCopy.Period;

	    PeriodCopy.Assign(PeriodCopied);

	    // Сохраняем копию

	    (ProblemCopy As IMetabaseObject).Save;

	    // Выполняем расчет задачи-копии

	    ProblemCalc := ProblemCopy.Calculate(CalcSettCopy);

	    ProblemCalc.Run;

	End Sub UserProc;

Sub UserProc;

	Var

	    mb: IMetabase;

	    DescrCM: IMetabaseObjectDescriptor;

	    pModel: IMsModel;

	    trans: IMsFormulaTransform;

	    coo: IMsFormulaTransformCoord;

	    calc: IMsMethodCalculation;

	    Period: IMsModelPeriod;

	    OutputPeriod: IMsDatePeriod;

	    StDate, EndDate: DateTime;

	Begin

	    // Получаем модель

	    mb := MetabaseClass.Active;

	    DescrCM := mb.ItemById("MS");

	    pModel := mb.ItemByIdNamespace("MODEL_FREEDIM", DescrCM.Key).Edit As IMsModel;

	    // Задаем параметры расчёта

	    trans := pModel.Transform;

	    coo := trans.CreateCoord(trans.Outputs.Item(0));

	    calc := trans.CreateCalculation;

	    // Задаем периоды расчета

	    Period := pModel.Transform.Period;

	    calc.Period.IdentificationStartDate := Period.IdentificationStartDate;

	    calc.Period.IdentificationEndDate := Period.IdentificationEndDate;

	    calc.Period.ForecastStartDate := Period.ForecastStartDate;

	    calc.Period.ForecastEndDate := Period.ForecastEndDate;

	    calc.CurrentPoint := Period.IdentificationStartDate;

	    OutputPeriod := trans.OutputPeriod As IMsDatePeriod;

	    // Очищаем параметры периода выгрузки данных

	    OutputPeriod.ClearPeriod;

	    // Задаем параметры автопериода: период выгрузки данных определяется текущей датой

	    OutputPeriod.AutoPeriod := MsDateAutoPeriodOptions.StartAsNow Or MsDateAutoPeriodOptions.EndAsNow;

	    // Задаем смещение дат начала и окончания периода выгрузки данных

	    OutputPeriod.StartOffset := 1;

	    OutputPeriod.EndOffset := 2;

	    // Получаем и выводим в окно консоли даты начала и окончания периода выгрузки данных

	    OutputPeriod.AutoPeriodDates(calc, coo, StDate, EndDate);

	    Debug.WriteLine("Начало выгрузки данных: " + StDate.ToString);

	    Debug.WriteLine("Окончание выгрузки данных: " + EndDate.ToString);

	    // Сохраняем изменения

	    (pModel As IMetabaseObject).Save;

	End Sub UserProc;

Sub UserProc;

	Var

	    mb: IMetabase;

	    ModelCont: IMetabaseObjectDescriptor;

	    Model: IMsModel;

	    Transform: IMsFormulaTransform;

	    Formula: IMsFormula;

	    DetermAggregation: IMsDetermAggregationTransform;

	    TermInfo: IMsFormulaTermInfo;

	    Stub: IVariableStub;

	    TransformVar: IMsFormulaTransformVariable;

	    SelectionFact: IDimSelectionSetFactory;

	    SelectionAgr, SelectionW, SelectionRel: IDimSelectionSet;

	    i: Integer;

	    DimI: IDimInstance;

	    Slice: IMsFormulaTransformSlice;

	Begin

	    // Получаем текущий репозиторий

	    mb := MetabaseClass.Active;

	    // Получаем контейнер моделирования

	    ModelCont := mb.ItemById("MS");

	    // Получаем модель

	    Model := mb.ItemByIdNamespace("MODEL_DETERM_AGGR", ModelCont.Key).Edit As IMsModel;

	    // Получаем параметры модели

	    Transform := Model.Transform;

	    Formula := Transform.FormulaItem(0);

	    Formula.Kind := MsFormulaKind.DetermAggregation;

	    DetermAggregation := Formula.Method As IMsDetermAggregationTransform;

	    // Создаем отметки для формирования выражений агрегации

	    Stub := (ModelCont.Bind As IMsModelSpace).DefaultObject.Bind As IVariableStub;

	    SelectionFact := New DimSelectionSetFactory.Create;

	    SelectionAgr := SelectionFact.CreateDimSelectionSet;

	    SelectionW := SelectionFact.CreateDimSelectionSet;

	    SelectionRel := SelectionFact.CreateDimSelectionSet;

	    For i := 0 To Stub.DimensionCount - 1 Do

	        DimI := (Stub.Dimension(i) As IMetabaseObject).Open(Null) As IDimInstance;

	        SelectionAgr.Add(DimI);

	        SelectionAgr.Item(i).SelectElement(i, False);

	        SelectionW.Add(DimI);

	        SelectionW.Item(i).SelectElement(i + 1, False);

	        SelectionRel.Add(DimI);

	        SelectionRel.Item(i).SelectElement(i + 2, False);

	    End For;

	    // Задаем выражение агрегации

	    TermInfo := Transform.CreateTermInfo;

	    TransformVar := Transform.Inputs.Add(Stub);

