	    SeasonalComp.Cycle := 5;

	    SeasonalComp.Mode := SeasonalityType.Multiplicative;

	    // Задаем значения параметров метода

	    Parameters := ExpSmooph.Parameters;

	    Parameters.Alpha := 0.06;

	    Parameters.Delta := 0.06;

	    Parameters.Gamma := 0.01;

