	    Descript := MB.ItemByIdNamespace("INPUT_FILL_GRAPS",ModelKey);

	    Obj_x1 := Descript.Bind;

	    ModelVar_x1 := Obj_x1 As IVariableStub;

	    Out := Transform.Outputs;

	    Out.Clear;

