// Выполнение автокорреляционного анализа

Sub UserAutoCorrelation;

Var

    mb: IMetabase;

    MsObj: IMetabaseObjectDescriptor;

    Problem: IMsProblem;

    Period: IMsModelPeriod;

    Meta: IMsMetaModel;

    MetaVisual: IMsMetaModelVisualController;

    VarKey, i: Integer;

    ChainEn: IMsCalculationChainEntries;

    ACF, PACF, QStatistics, Probability: Array Of Double;

    StandardError: Double;

Begin

    mb := MetabaseClass.Active;

    // Получаем контейнер моделирования

    MsObj := mb.ItemById("MS");

    // Получаем задачу моделирования

    Problem := mb.ItemByIdNamespace("PROBLEM", MsObj.Key).Bind As IMsProblem;

    // Получаем метамодель

    Meta := Problem.MetaModel;

    // Получаем период расчёта

    Period := (Problem.Details As IMsProblemDetails).Period;

    // Получаем 1-ю свободную переменную

    ChainEn := Meta.CalculationChain;

    VarKey := -1; i := 0;

    Repeat

        If ChainEn.Item(i).Type = MsCalculationChainEntryType.Variable Then

            VarKey := ChainEn.Item(i).Key;

        End If;

        i := i + 1;

    Until (VarKey = -1) Or (i <> ChainEn.Count);

    // Если переменная найдена, то выполняем автокорреляционный анализ

    If VarKey <> -1 Then

        MetaVisual := Meta.VisualController;

        Debug.WriteLine(MetaVisual.AutoCorrelation(VarKey, Period, ACF, PACF, QStatistics, Probability, StandardError));

        Debug.WriteLine("Значения автокорреляционной функции");

        PrintArray(ACF);

        Debug.WriteLine("Значения частной автокорреляционной функции");

        PrintArray(PACF);

        Debug.WriteLine("Значения q - статистики Льюнга-Бокса");

        PrintArray(QStatistics);

        Debug.WriteLine("Значения вероятности q - статистики Льюнга-Бокса");

        PrintArray(Probability);

        Debug.WriteLine("Значение стандартной ошибки автокорреляционной функции");

        Debug.WriteLine(StandardError);

    End If;

End Sub UserAutoCorrelation;

// Процедура вывода данных

Sub PrintArray(arr: Array Of Double);

Var i: Integer;

Begin

    For i := 0 To arr.Length - 1 Do

        Debug.WriteLine(arr[i]);

    End For;

    Debug.WriteLine("");

End Sub PrintArray;

Sub UserProc;

Var MB: IMetabase;

    Model: IMsModel;

    Transform: IMsFormulaTransform;

    VarTrans: IMsFormulaTransformVariable;

    Tree: IMsFormulaTransformSlicesTree;

    Slice: IMsFormulaTransformSlice;

    Selector: IMsFormulaTransformSelector;

    Formula: IMsFormula;

    LinReg: IMsLinearRegressionTransform;

    Coord: IMsFormulaTransformCoord;

    Calc: IMsModelCalculation;

    CalcRes: IMsTransformSeries;

    d: Double;

Begin

    // Получаем текущий репозиторий

    MB := MetabaseClass.Active;

    // Получаем модель

    Model := MB.ItemByIdNamespace("MODEL_LINREG", MB.ItemById("MS").Key).Bind As IMsModel;

    // Получаем параметры модели

    Transform := Model.Transform;

    VarTrans := Transform.Outputs.Item(0);

    Tree := VarTrans.SlicesTree(VarTrans);

    Slice := Tree.CreateSlice(1);

    Selector := Transform.CreateSelector;

    Selector.Slice := Slice;

    Formula := Transform.Transform(Selector);

    LinReg := Formula.Method As IMsLinearRegressionTransform;

    Coord := Transform.CreateCoord(VarTrans);

    // Создаем объект для расчета модели

    Calc := Model.CreateCalculation;

    // Задаем периоды расчета

    Calc.Period.IdentificationStartDate := DateTime.Parse("01.01.2000");

    Calc.Period.IdentificationEndDate := DateTime.Parse("31.12.2005");

    Calc.Period.ForecastStartDate := DateTime.Parse("01.01.2006");

    Calc.Period.ForecastEndDate := DateTime.Parse("31.12.2010");

    // Выполняем расчет

    CalcRes := LinReg.CalculateSeries(Calc As IMsMethodCalculation, Coord);

    // Выводим результаты расчета в окно консоли

    Debug.WriteLine("Исходный ряд:");

    For Each d In CalcRes.Fact Do

        Debug.WriteLine(d.ToString);

    End For;

    Debug.WriteLine("");

    Debug.WriteLine("Модельный ряд:");

    For Each d In CalcRes.Modelling Do

        Debug.WriteLine(d.ToString);

    End For;

    Debug.WriteLine("");

    Debug.WriteLine("Остатки:");

    For Each d In CalcRes.Residuals Do

        Debug.WriteLine(d.ToString);

    End For;

    Debug.WriteLine("");

    Debug.WriteLine("Прогноз:");

    For Each d In CalcRes.Forecast Do

        Debug.WriteLine(d.ToString);

    End For;

    Debug.WriteLine("");

    Debug.WriteLine("Верхняя доверительная граница:");

    For Each d In CalcRes.UpperConfidenceLevel Do

        Debug.WriteLine(d.ToString);

    End For;

    Debug.WriteLine("");

    Debug.WriteLine("Нижняя доверительная граница:");

    For Each d In CalcRes.LowerConfidenceLevel Do

        Debug.WriteLine(d.ToString);

    End For;

End Sub UserProc;

Sub UserProc;

Var

    Mb: IMetabase;

    Rubr: IRubricator;

    Model: IMsModel;

    FormulasList: IMsAttributesFormulasList;

    AttrTranfsorm: IMsFormulaTransform;

    ModelTransform: IMsFormulaTransform;

    ModelOutputs: IMsFormulaTransformVariables;

    OutputVar: IMsFormulaTransformVariable;

    AttrOutputs: IMsFormulaTransformVariables;

    TransVar: IMsFormulaTransformVariable;

    OutputSlices: IMsFormulaTransformSlices;

    SelectionSet: IDimSelectionSet;

    Slice: IMsFormulaTransformSlice;

    AttrValueList: IMsMetaAttributeValueList;

    RubrMetaAttrs: IMetaAttributes;

    RubrAttr: IMetaAttribute;

    AttrVal: IMsMetaAttributeValue;

    Selector: IMsFormulaTransformSelector;

    Formula: IMsFormula;

    Determ: IMsDeterministicTransform;

    Expr: IExpression;

    DetermOperands: IMsFormulaTermList;

    tInfo: IMsFormulaTermInfo;

Begin

    Mb := MetabaseClass.Active;

    Rubr := Mb.ItemById("OBJ_RUBRICATOR").Bind As IRubricator;

    Model := Mb.ItemByIdNamespace("MODEL", Rubr.ModelSpace.Key).Edit As IMsModel;

    ModelTransform := Model.Transform;

    ModelOutputs := ModelTransform.Outputs;

    OutputVar := ModelOutputs.Item(0);

    // Получаем список методов, по которым будут рассчитываться дополнительные атрибуты

    FormulasList := Model.AttributeFormulasList;

    FormulasList.Clear;

    // Добавляем новый метод расчета дополнительного атрибута и задаем его параметры

    AttrTranfsorm := FormulasList.Add;

    AttrOutputs := AttrTranfsorm.Outputs;

    TransVar := AttrOutputs.Add(OutputVar.VariableStub);

    TransVar.AttributeId := "COMM";

    OutputSlices := OutputVar.Slices;

    SelectionSet := OutputSlices.Item(0).Selection;

    Slice := TransVar.Slices.Add(SelectionSet);

    AttrValueList := Slice.MetaAttributeValueList;

    AttrValueList.Clear;

    RubrMetaAttrs := Rubr.Facts.Attributes;

    RubrAttr := RubrMetaAttrs.FindById("COMM");

    AttrVal := AttrValueList.Add(RubrAttr);

    AttrVal.Kind := MsMetaAttributeValueType.Unspecified;

    Selector := AttrTranfsorm.CreateSelector;

    Selector.Slice := Slice;

    Formula := AttrTranfsorm.Transform(Selector);

    Formula.Kind := MsFormulaKind.Deterministic;

    Determ := Formula.Method As IMsDeterministicTransform;

    DetermOperands := Determ.Operands;

    DetermOperands.Clear;

    tInfo := DetermOperands.Add(Slice).TermInfo;

    Expr := Determ.Expression;

    Expr.AsString := "iif(" + tInfo.TermInnerText + "<>""""," + tInfo.TermInnerText + ",""Комментарий отсутствовал"")";

    If Not (Expr.Valid)

        Then Debug.WriteLine(expr.ErrorInfo.ErrorMessage);

        Else (Model As IMetabaseObject).Save;

    End If;

End Sub UserProc;

