Sub UserProc;

Var

    mb: IMetabase;

    MsKey: Integer;

    pMetaModelSrc, pMetaModelDest: IMsMetaModel;

    param: IMsModelParam;

    params: IMsModelParams;

    branchScr, branchDest: IMsCalculationChainBranch;

    cas, casDest: IMsBranchCase;

    pCondExpr, pCondExprDest: IMsBranchConditionExpression;

    expr, exprDest: IExpression;

    CalcChain: IMsCalculationChainEntries;

    CalcEntry: IMsCalculationChainEntry;

    i, k, n: Integer;

    CondDest: IMsBranchCondition;

    gen: IMsTransformStringGenerator;

    s: String;

Begin

    mb := MetabaseClass.Active;

    // Получаем контейнер моделирования

    MsKey := mb.GetObjectKeyById("MS");

    // Получаем метамодель

    pMetaModelSrc := mb.ItemByIdNamespace("METAMODEL", MsKey).Edit As IMsMetaModel;

    // Создаем параметр в метамодели

    params := pMetaModelSrc.Params;

    params.Clear;

    param := params.Add;

    param.Hidden := True;

    param.LinkedObject := mb.ItemByIdNamespace("DIC_COUNTRY", mb.GetObjectKeyById("MDM_REPO")).Bind;

    param.DataType := DbDataType.String;

    // Очищаем цепочку расчета метамодели

    pMetaModelSrc.CalculationChain.Clear;

    // Добавляем условие в цепочку расчета метамодели

    branchScr := pMetaModelSrc.CalculationChain.AddBranch("Условие");

    // Задаем параметр условия

    branchScr.Parameter := param;

    // Создаем ветку условия

    cas := branchScr.CaseList.Add;

    // Задаем модель, которая будет рассчитываться, если не выполнилась ни одна из веток условия

    branchScr.DefaultContents.AddModel(mb.ItemByIdNamespace("MODEL_DEFAULT", MsKey).Bind As IMsModel);

    // Задаем модель, которая рассчитывается при выполнении условия

    cas.Contents.AddModel(mb.ItemByIdNamespace("MODEL", MsKey).Bind As IMsModel);

    // Задаем условие расчета ветки

    pCondExpr := cas.Conditions.Add(MsBranchConditionType.Expression) As IMsBranchConditionExpression;

    expr := pCondExpr.Expression;

    expr.AsString := "{" + param.Id + "}=" + """" + "Мир" + """";

    If expr.ErrorInfo <> Null

        Then

            // Если в выражении есть ошибка, то выводим её в окно консоли

            Debug.WriteLine(expr.ErrorInfo.ErrorMessage);

        Else

            // Сохраняем изменения  в метамодели

            (pMetaModelSrc As IMetabaseObject).Save;

            // Получаем метамодель, в которую будем копировать выражение для расчета условия

            pMetaModelDest := mb.ItemByIdNamespace("METAMODEL_DEST", MsKey).Edit As IMsMetaModel;

            // Создаем параметр в метамодели

            params := pMetaModelSrc.Params;

            params.Clear;

            param := params.Add;

            param.Hidden := True;

            param.LinkedObject := mb.ItemByIdNamespace("DIC_COUNTRY", mb.GetObjectKeyById("MDM_REPO")).Bind;

            param.DataType := DbDataType.String;

            // Получаем цепочку расчета метамодели

            CalcChain := pMetaModelDest.CalculationChain;

            For i := 0 To CalcChain.Count - 1 Do

                CalcEntry := CalcChain.Item(i);

                // Получаем условия из цепочки расчета

                If CalcEntry.Type = MsCalculationChainEntryType.Branch Then

                    branchDest := CalcEntry As IMsCalculationChainBranch;

                    // Перебираем ветки условия

                    For k := 0 To branchDest.CaseList.Count - 1 do

                        casDest := branchDest.CaseList.Item(k);

                        // Отбираем условные ветки

                        For n := 0 To casDest.Conditions.Count - 1 Do

                            CondDest := casDest.Conditions.Item(n);

                            // Копируем выражение условия из одной ветки в другую

                            If CondDest.Type = MsBranchConditionType.Expression Then

                                pCondExprDest := CondDest As IMsBranchConditionExpression;

                                gen := pCondExpr.Transform.CreateStringGenerator;

                                s := gen.Execute;

                                s := String.Remove(s, 0, 3);

                                exprDest := pCondExprDest.Expression;

                                exprDest.AsString := s;

                                If exprDest.ErrorInfo <> Null Then

                                    // Если в выражении есть ошибка, то выводим её в окно консоли

                                    Debug.WriteLine("Выражение условия содержит ошибку: " + exprDest.ErrorInfo.ErrorMessage);

                                    Else

                                        // Сохраняем изменения в метамодели

                                        (pMetaModelDest As IMetabaseObject).Save;

                                End If;

                            End If;

                        End For;

                    End For;

                End If;

            End For;

    End If;

End Sub UserProc;

Sub ModelAttr;

Var

    Mb: IMetabase;

    CrInf: IMetabaseObjectCreateInfo;

    Model: IMsModel;

    Transform: IMsFormulaTransform;

    TransformVarables: IMsFormulaTransformVariables;

    RubrDescr: IMetabaseObjectDescriptor;

    Stub: IVariableStub;

    TransVar: IMsFormulaTransformVariable;

    Tree: IMsFormulaTransformSlicesTree;

    Slice: IMsFormulaTransformSlice;

    Selector: IMsFormulaTransformSelector;

    Formula: IMsFormula;

    Linear: IMsLinearRegressionTransform;

    Ar: Array[0..1] Of Integer;

    TermInfo: IMsFormulaTermInfo;

    Period: IMsModelPeriod;

Begin

    Mb := MetabaseClass.Active;

    // Задаем базовые параметры модели как объекта репозитория

    CrInf := Mb.CreateCreateInfo;

    CrInf.ClassId := MetabaseObjectClass.KE_CLASS_MSMODEL;

    // Задаем идентификатор модели

    CrInf.Id := Mb.GenerateId("MODEL_LINEAR_REGRESSION", Mb.ItemById("MS").Key);

    // Задаем наименование модели

    CrInf.Name := "Модель линейной регрессии";

    // Задаем контейнер моделирования, в котором будет создаваться модель

    CrInf.Parent := Mb.ItemById("MS");

    // Создаем модель

    Model := Mb.CreateObject(CrInf).Edit As IMsModel;

    // Получаем объект для настройки параметров модели

    Transform := Model.Transform;

    // Получаем объект для работы с моделируемой переменной

    TransformVarables := Transform.Outputs;

    // Получаем базу данных временных рядов (БДВР)

    RubrDescr := Mb.ItemById("TSDB");

    // Приводим полученную БДВР к абстрактному источнику данных

    Stub := RubrDescr.Bind As IVariableStub;

    // Используем БДВР в качестве источника данных моделируемой переменной

    TransVar := TransformVarables.Add(Stub);

    // Задаем срез моделируемой переменной

    Tree := TransVar.SlicesTree(TransVar);

    Slice := Tree.CreateSlice(1);

    // Получаем настройки модели для среза моделируемой переменной

    Selector := Transform.CreateSelector;

    Selector.Slice := Slice;

    Formula := Transform.Transform(Selector);

    // Указываем метод расчета - Линейная регрессия (оценка МНК)

    Formula.Kind := MsFormulaKind.LinearRegression;

    // Задаем календарную динамику расчета

    Formula.Level := DimCalendarLevel.Year;

    // Получаем объект для настройки линейной регрессии

    Linear := Formula.Method As IMsLinearRegressionTransform;

    // Задаем порядок авторегрессии

    Ar[0] := 2;

    Ar[1] := 4;

    Linear.ARMA.OrderAR := Ar;

    // Используем автоматическую оценку константы

    Linear.ConstantMode := InterceptMode.AutoEstimate;

    // Добавляем в модель фактор, источником данных которого является БДВР

    TransVar := Transform.Inputs.Add(Stub);

    Tree := TransVar.SlicesTree(TransVar);

    Slice := Tree.CreateSlice(2);

    // Получаем фактор в виде элемента выражения

    TermInfo := Transform.CreateTermInfo;

    TermInfo.Slice := Slice;

    // Задаем формулу расчета линейной регрессии

    Linear.Explanatories.Add.Expression.AsString := TermInfo.TermInnerText;

    // Задаем периоды расчета модели

    Period := Transform.Period;

    Period.IdentificationStartDate := DateTime.ComposeDay(2000, 1, 1);

    Period.IdentificationEndDate := DateTime.ComposeDay(2014, 12, 31);

    Period.ForecastStartDate := DateTime.ComposeDay(2015, 1, 1);

    Period.ForecastEndDate := DateTime.ComposeDay(2020, 12, 31);

    // Сохраняем модель в репозитории

    (Model As IMetabaseObject).Save;

End Sub ModelAttr;

Sub UserProc;

Var

    mb: IMetabase;

    MsKey: Integer;

    pMetaModel: IMsMetaModel;

    Ms: IMsModelSpace;

    DS: IRubricator;

    Attributes: IMetaAttributes;

    CDict, IDict: IMetabaseObjectDescriptor;

    Chain: IMsCalculationChainEntries;

    params: IMsModelParams;

    CParam, IParam: IMsModelParam;

    iterator: IMsCalculationChainMultiDimIterator;

    IteratorOpt: IMsDimIterateByDataOptions;

    IterStubs: IMsDimIterateByDataStubs;

    dimInstC, dimInstI: IDimInstance;

    IterDims: IMsDimIteratorDimensions;

    CIterDim, IIterDim: IMsDimIteratorDimension;

    Filter: IMsDimIteratorFilter;

    dimSelC, dimSelI: IDimSelection;

    IterStub: IMsDimIterateByDataStub;

    FilterDim: IMsDimIteratorFilteredDimension;

    model: IMsModel;

    Trans: IMsFormulaTransform;

    TransVar: IMsFormulaTransformVariable;

    slice: IMsFormulaTransformSlice;

    Selector: IMsFormulaTransformSelector;

    Formula: IMsFormula;

    Determ: IMsDeterministicTransform;

    TermInfo: IMsFormulaTermInfo;

    Expr: IExpression;

Begin

    // Получаем текущий репозиторий

    mb := MetabaseClass.Active;

    // Получаем ключ контейнера моделирования

    MsKey := mb.GetObjectKeyById("MS");

    // Получаем модель

    pMetaModel := mb.ItemByIdNamespace("METAMODEL_MULTIDIMITERATOR", MsKey).edit As IMsMetaModel;

    // Получаем контейнер моделирования

    Ms := mb.Item(MsKey).Bind As IMsModelSpace;

    // Получаем базу данных временных рядов,

    // являющуюся источником данных для контейнера моделирования

    DS := Ms.Rubricator.Bind As IRubricator;

    // Получаем атрибуты показателей

    Attributes := DS.Facts.Attributes;

    // Получаем справочники, на которых основаны атрибуты CITY и INDICATOR

    CDict := Attributes.FindById("CITY").ValuesObject;

    IDict := Attributes.FindById("INDICATOR").ValuesObject;

    // Получаем и очищаем цепочку расчета метамодели

    Chain := pMetaModel.CalculationChain;

    Chain.Clear;

    // Получаем и очищаем параметры метамодели

    params := pMetaModel.Params;

    params.Clear;

    // Добавляем параметр, основанный на справочнике атрибута CITY

    CParam := params.Add;

    CParam.DataType := DbDataType.integer;

    CParam.DefaultValue := 1;

    CParam.Hidden := True;

    CParam.Id := "CITY";

    CParam.Name := "Город";

    CParam.LinkedObject := CDict;

    // Добавляем параметр, основанный на справочнике атрибута INDICATOR

    IParam := params.Add;

    IParam.DataType := DbDataType.Integer;

    IParam.DefaultValue := 1;

    IParam.Hidden := True;

    IParam.Id := "INDICATOR";

    IParam.Name := "Показатель";

    IParam.LinkedObject := IDict;

    // Добавляем многомерный итератор в цепочку расчета метамодели

    iterator := Chain.AddMultiDimIterator("Многомерный итератор");

    // Получаем параметры итератора по данным

    IteratorOpt := Iterator.IterateByData;

    // Указываем, что он активный

    IteratorOpt.Active := True;

    // Задаем источник данных для итератора

    IterStubs := IteratorOpt.Stubs;

    IterStubs.Add(DS As IVariableStub);

    // Получаем итерируемые измерения

    IterDims := Iterator.Dimensions;

    // Добавляем измерение, основанное на справочнике атрибута CITY

    dimInstC := CDict.Open(Null) As IDimInstance;

    CIterDim := IterDims.Add(dimInstC);

    // Указываем, что измерение параметрическое

    CIterDim.Parameter := CParam;

    // Задаем источник данных для итерируемого измерения

    CIterDim.Stubs.Add(DS As IVariableStub);

    // Задаем фильтр элементов

    Filter := CIterDim.Filter;

    dimSelC := dimInstC.CreateSelection;

    dimSelC.SelectAll;

    Filter.Selection := dimSelC;

    // Добавляем измерение, основанное на справочнике атрибута INDICATOR

    dimInstI := IDict.Open(Null) As IDimInstance;

    IIterDim := IterDims.Add(dimInstI);

    // Указываем, что измерение параметрическое

    IIterDim.Parameter := IParam;

    // Задаем источник данных для итерируемого измерения

    IIterDim.Stubs.Add(DS As IVariableStub);

    // Задаем фильтр элементов

    Filter := IIterDim.Filter;

    dimSelI := dimInstI.CreateSelection;

    dimSelI.SelectAll;

    Filter.Selection := dimSelI;

    // Получаем источник данных, по которому которому будут выполняться итерации

    IterStub := IterStubs.Item(0);

    // Добавляем фильтрацию по измерению, на котором основан атрибут CITY

    FilterDim := IterStub.Dimension(dimInstC.InstanceModel);

    Debug.WriteLine("  Измерение фильтрации: " + FilterDim.Dimension.Name);

    FilterDim.Filter.Selection := dimSelC;

    // Добавляем фильтрацию по измерению, на котором основан атрибут INDICATOR

    FilterDim := IterStub.Dimension(dimInstI.InstanceModel);

    FilterDim.Filter.Selection := dimSelI;

    Debug.WriteLine("  Измерение фильтрации: " + FilterDim.Dimension.Name);

    // Создаем внутри многомерного итератора модель

    model := Iterator.Contents.AddExclusiveModel.Model;

    // Настраиваем модель

    Trans := model.Transform;

    // Добавляем моделируемую переменную, атрибуты которой заданы параметрами

    TransVar := Trans.Outputs.Add(DS As IVariableStub);

    Slice := TransVar.Slices.Add(Null);

    Slice.ParametrizedDimensions.Item(0).Parameter := IParam;

    Slice.ParametrizedDimensions.Item(1).Parameter := CParam;

    Selector := Trans.CreateSelector;

    Selector.Slice := Slice;

    // Настраиваем метод расчета модели: детерминированное уравнение

    Formula := Trans.Transform(Selector);

    Formula.Kind := MsFormulaKind.Deterministic;

    Determ := Formula.Method As IMsDeterministicTransform;

    // Добавляем входную переменную, атрибуты которой заданы параметрами

    TransVar := Trans.Inputs.Add(DS As IVariableStub);

    Slice := TransVar.Slices.Add(Null);

    Slice.ParametrizedDimensions.Item(0).Parameter := IParam;

    Slice.ParametrizedDimensions.Item(1).Parameter := CParam;

    TermInfo := Trans.CreateTermInfo;

    TermInfo.Slice := Slice;

    // Задаем выражение для расчета модели

    Expr := Determ.Expression;

    Expr.AsString := TermInfo.TermInnerText + "+1";

    If Expr.ErrorInfo <> Null Then

        debug.WriteLine(Expr.ErrorInfo.ErrorMessage);

        Return;

    End If;

    // Сохраняем изменения в модели

    model.MetabaseObject.Save;

    // Сохраняем изменения в метамодели

    (pMetaModel As IMetabaseObject).Save;

End Sub UserProc;

