Sub UserProc;

Var

    MB: IMetabase;

    TSDB: IRubricator;

    Facts: IMetabaseObject;

    Atts: IMetaAttributes;

    Att: IMetaAttribute;

Begin

    // Получаем текущий репозиторий

    MB := MetabaseClass.Active;

