    Attribute.Nullable := False;

    Attribute.HasMultipleValues := False;

    Attribute.DataType := DbDataType.Integer;

    Attribute.ValuesObject := Mb.ItemByIdNamespace("DICT_IND", RdsDescr.Key).Bind;

