    Index.Unique := True;

    Attributes := Facts.Attributes;

    AttrColl := Index.Attributes;

    Attribute := Attributes.FindById("COUNTRY");

    AttrColl.Add(Attribute);

    Attribute := Attributes.FindById("INDICATOR");

    AttrColl.Add(Attribute);

    Attributes.CreateTable;

