Sub UserProc;

Var

    Mb: Imetabase;

    Rubr: IMetabaseObject;

    RubrInst: IRubricatorInstance;

    Facts: IMetaDictionaryInstance;

    Hierarchy: IMetaHierarchy;

    HInstance: IMetaHierarchyInstance;

    Mem: IMetaMember;

    Conds: IOrmConditions;

    con: IOrmCondition;

    Mems: IMetaMembers;

Begin

    Mb := MetabaseClass.Active;

    Rubr := MB.ItemById("OBJ_FC").Bind;

    RubrInst := Rubr.Open(Null) As IRubricatorInstance;

    Facts := RubrInst.GetDictionary(RubricatorDictionary.Facts);

    Hierarchy := Facts.Dictionary.DefaultHierarchy;

    HInstance := Facts.OpenHierarchy(Hierarchy);

    Mems := HInstance.GetRootMembers;

    Mem := Mems.Current;

    Debug.WriteLine("До");

    Debug.WriteLine(Mem.CountTotal);

    Conds := HInstance.CustomWhere;

    con := Conds.Add;

    con.AttributeName := "COUNTRY";

    con.Value := 512;

    HInstance.Build;

    Mems := HInstance.GetRootMembers;

    Mem := Mems.Current;

    Debug.WriteLine("После");

    Debug.WriteLine(Mem.CountTotal);

End Sub UserProc;

Sub UserProc;

Var

   mb: IMetabase;

    RubDesc: IMetabaseObjectDescriptor;

    RubrIn: IRubricatorInstance;

    DictInst: IMetaDictionaryInstance;

    HieDef: IMetaHierarchy;

    HieInst: IMetaHierarchyInstance;

    Mems: IMetaMembers;

Begin

    mb := MetabaseClass.Active;

    RubDesc := mb.ItemById("FC_COMM");

    RubrIn := RubDesc.Open(Null) As IRubricatorInstance;

    DictInst := RubrIn.GetDictionary(RubricatorDictionary.Facts);

    HieDef := DictInst.Dictionary.DefaultHierarchy;

    HieDef.Attributes.MoveAllTo(HieDef.Attributes, HieDef.Levels.Leaf);

// Установили ограничение

    HieDef.LeafLoadExtent := 128;

    HieInst := DictInst.OpenHierarchy(HieDef);

    Mems := HieInst.GetRootMembers;

    Mems.Reset;

    Repeat

        Debug.WriteLine(Mems.Current.Name);

        Mems.Next;

    Until Not Mems.Eof;

End Sub UserProc;

