	        Case TabObjectChangeType.Rect:

	            Rect := Args As IReportBeforeObjectRectChangeEventArgs;

	            RectPos := Rect.NewValue;

	            If RectPos.Bottom > 100 Then

	                Rect.Cancel := True;

	            End If;

	    End Select;

