    User: IMetabaseUser;

    Data: ISecurityPackageUserData;

    Package: ISecurityPackage;

    PswCreds: IPasswordCredentials;

    Profs: IUserProfiles;

    Prof: IUserProfile;

    Lic: Object;

Begin

    MB := MetabaseClass.Active;

    // Получим лицензию для возможности работы с менеджером безопасности

