	    Sub Sleep(Millisecs: Integer);

	    Var

	        J, I: Integer;

	    Begin

	        I := (Millisecs + 999) Div 1000;

	        While I > 0 Do

	            For J := 0 To 999 Do

	                If Millisecs > 0 Then

	                    Millisecs := Millisecs - 1;

	                Else

	                    I := 0;

	                    Break;

	                End If;

	            End For;

	            I := I - 1;

	        End While;

	    End Sub Sleep;

