	Public Function min_r(q: Array Of Double): Variant;

	Var

	    min: Double;

	    i: Integer;

	Begin

	    min := Double.MinValue;

	    For i := 0 To q.Length - 1 Do

	        If q[i] > min Then

	            min := q[i];

	        End If;

	    End For;

	    Return min;

	End Function min_r;

