    pInputSlice := pTransform.Inputs.Add(pSeries.Stub).Slices.Add(Null);

    pTerm := pIdentity.Operands.Add(pInputSlice);

    pIdentity.Expression.AsString := pTerm.TermToInnerText + " + 10";

