	    Task.PlanPeriod.Duration := 10;

	    Depend := Task.Dependencies.Add;

	    Depend.PredecessorTaskKey := 3;

	    Depend.Type := PrjTaskDependencyType.FinishToFinish;

	    // Добавим третью задачу

