                    DepCell := DepRange.Part(j);

                    Style := DepCell.Style;

                    Style.BorderColor(TabBorder.Outline) := GxColor.FromName("Red");

                    Style.BorderStyle(TabBorder.Outline) := TabBorderStyle.Continuous;

                End For;

            End For;

