Sub UserProc;

Var

    tstyle : ITabTableStyle;

    tab : ITabSheet;

    i : Integer;

    s : String;

Function getst(j : String): String;

Var t : String;

    Begin

    Select Case j

        Case "-1": t := "Undefined";

        Case "0": t := "Blue";

        Case "1": t := "DarkBlue";

        Case "2": t := "Red";

        Case "3": t := "DarkRed";

        Case "4": t := "Green";

        Case "5": t := "DarkGreen";

        Case "6": t := "Purple";

        Case "7": t := "DarkPurple";

        Case "8": t := "Orange";

        Case "9": t := "DarkOrange";

    End Select;

    Return t;

End Function getst;

Begin

    tab := (PrxReport.ActiveReport.ActiveSheet As IPrxTable).TabSheet;

    For i := 0 To tab.TableStyles.Count - 1 Do

        tstyle := tab.TableStyles.Item(i);

        s := s + tstyle.Name + ": " + getst(tstyle.PredefinedStyle.ToString) + #13+#10;

    End For;

    WinApplication.InformationBox(s);

End Sub UserProc;

